import{_ as o,o as t,c as i,a7 as n}from"./chunks/framework.DPOEA7Ka.js";const p=JSON.parse('{"title":"Analyse Frontend — Régions","description":"","frontmatter":{"title":"Analyse Frontend — Régions","outline":[2,3]},"headers":[],"relativePath":"modernisation/frontend/regions.md","filePath":"modernisation/frontend/regions.md"}'),r={name:"modernisation/frontend/regions.md"};function s(d,e,a,c,l,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="analyse-frontend-—-regions" tabindex="-1">Analyse Frontend — Régions <a class="header-anchor" href="#analyse-frontend-—-regions" aria-label="Permalink to &quot;Analyse Frontend — Régions&quot;">​</a></h1><p class="feature-badges"><span class="badge badge-todo">0 / 13 tâches Processed</span> <span class="section-label front">Frontend</span> <span class="badge badge-spec">React 19</span> <span class="dash-status blue">Planifiée — 34 tâches</span></p><div class="info custom-block"><p class="custom-block-title">Source</p><p>Copie de <code>output/analysis/frontend/Regions_frontend_analysis.md</code> (planification du 2026-10-10, 13 tâches <code>FRONTEND-001</code> → <code>FRONTEND-013</code>, toutes <code>Unprocessed</code>). Voir aussi la <a href="./../regions">timeline de la feature</a>, l&#39;<a href="./../api/regions">analyse API</a> et la <a href="/modernize-legacy/exemple-wiki-legacy/docs/features/regions">spécification</a> (<a href="/modernize-legacy/exemple-wiki-legacy/docs/features/regions#sec-13">écarts arbitrés</a>).</p></div><h2 id="resume" tabindex="-1">Résumé <a class="header-anchor" href="#resume" aria-label="Permalink to &quot;Résumé&quot;">​</a></h2><p>La feature Regions expose côté frontend (1) une page publique « Régions » qui affiche l&#39;arbre à 2 niveaux (racines + sous-régions triées par position) avec des liens vers la future recherche d&#39;annonces par <code>slug</code> en conservant les autres filtres de la query string (#sec-3 Scénario 1, CL-14), (2) un composant partagé de liste déroulante de région (#sec-3 Scénario 2) destiné aux features consommatrices, et (3) un espace d&#39;administration réservé au rôle admin : liste paginée par niveau, création (slug obligatoire, bouton « Générer » via l&#39;API), modification (changement de parent réservé aux sous-régions, RM-05), suppression avec confirmation (409 si sous-régions, E-01) et réordonnancement haut/bas.</p><p>C&#39;est le <strong>jumeau de Categories</strong> : le socle frontend (client HTTP, jeton admin, <code>AdminAccessGate</code>, patterns table/formulaire) est déjà migré et sera réutilisé. Les <strong>règles sont celles de la spec Regions</strong>, plus étroites que celles de Categories (voir « Différences avec Categories »). Le design Figma n&#39;existe pas (<code>output/design/</code> vide) : la skill <code>front-design-conventions</code> s&#39;applique uniquement par ses règles responsive générales.</p><h2 id="contexte-d-implementation-source" tabindex="-1">Contexte d&#39;Implémentation Source <a class="header-anchor" href="#contexte-d-implementation-source" aria-label="Permalink to &quot;Contexte d&#39;Implémentation Source&quot;">​</a></h2><ul><li><strong>Stack UI Actuelle</strong> : PHP procédural (Page Controllers) + templates PHP, aucun JavaScript hormis <code>confirm()</code> natif, pagination PEAR Pager (admin, 10/page), aucune API JSON.</li><li><strong>Composants Source</strong> : <ul><li>Public : <code>php-legacy/region-list.php</code>, <code>php-legacy/templates/region-list.php</code> (blocs de 3 colonnes <code>#regions</code>, classes <code>category-block</code>/<code>categs</code> réutilisées, liens <code>ad-list.php?region={slug}&amp;pageID=0</code> + GET courants via <code>build_query_string</code>, <code>common.php:203-218</code>), <code>templates/layout/page-top.php:41</code> (lien menu).</li><li>Selects : <code>templates/parts/select-region.php</code> (valeur <code>id</code>), <code>templates/forms/ad-search-form.php:31-45</code> (valeur <code>slug</code>, option « Any »).</li><li>Admin : <code>php-legacy/admin/region-list.php</code> (10/page, Id/Name/Operations, Edit/Delete/Up/Down/« Subcategories(n) »), <code>admin/region-create.php</code> (Parent, Name, Slug, Generate), <code>admin/region-edit.php</code> (Name, Slug, Parent seulement pour sous-région, Modify/Reset, saisie d&#39;Id).</li></ul></li><li><strong>Gestion d&#39;État</strong> : aucune côté client ; contexte admin (<code>parent</code>, <code>pageID{parent}</code>) dans la query string.</li><li><strong>Navigation</strong> : liens/formulaires HTML, actions destructrices en GET (<code>?d=</code>, <code>?o=&amp;r=</code>) remplacées par DELETE/POST (T-02).</li><li><strong>Pattern UI</strong> : rendu serveur (Page Controller + template).</li></ul><h2 id="contexte-d-implementation-frontend" tabindex="-1">Contexte d&#39;Implémentation Frontend <a class="header-anchor" href="#contexte-d-implementation-frontend" aria-label="Permalink to &quot;Contexte d&#39;Implémentation Frontend&quot;">​</a></h2><p>Constaté dans <code>app-react-target/</code> (Glob/Read) :</p><ul><li><strong>Stack Frontend</strong> : React 19 + TypeScript strict, Vite, React Router 7 (<code>createBrowserRouter</code>, routes <code>lazy</code>), TanStack Query v5, Zustand, React Hook Form + Zod, Tailwind CSS 4 + Shadcn/ui (New York), sonner, lucide-react, Vitest + RTL + MSW.</li><li><strong>Architecture</strong> : <code>Route (app/routes) → Feature (features) → Hook (hooks) → API (api) → lib/api-client</code> (<code>.claude/skills/front-app-conventions/references/architecture.md</code>).</li><li><strong>Déjà présent et réutilisé tel quel</strong> : <code>lib/api-client.ts</code> (base = origine seule, chemins <code>/api/...</code>, <code>skipAuth</code>), <code>lib/auth-token.ts</code>, <code>hooks/use-auth-token.ts</code>, <code>lib/error-handler.ts</code>, <code>types/api.ts</code> (<code>PaginatedResponse</code>), <code>lib/slug.ts</code> (non réutilisé ici), <code>features/admin/{admin-access-gate,admin-token-form,admin-error-alert}.tsx</code> (l&#39;invalidation du formulaire de jeton est déjà générique : <code>invalidateQueries()</code> sans clé), composants Shadcn <code>table</code>, <code>alert-dialog</code>, <code>alert</code>, <code>button</code>, <code>input</code>, <code>field</code>, <code>card</code>, <code>breadcrumb</code>, <code>skeleton</code>, <code>spinner</code>, <code>empty</code>, <code>badge</code>.</li><li><strong>À adapter</strong> : <code>features/admin/admin-breadcrumb.tsx</code> (libellé « Catégories » et lien codés en dur), <code>components/layout/app-layout.tsx</code> (tableau <code>navLinks</code> à étendre), <code>app/router.tsx</code> (routes), <code>tests/mocks/handlers.ts</code> (handlers).</li><li><strong>Modèle à imiter</strong> : <code>features/categories/**</code>, <code>api/category.ts</code>, <code>hooks/use-categories.ts</code>, <code>schemas/category.ts</code>, <code>lib/category-links.ts</code>, <code>lib/category-error-messages.ts</code>, routes <code>app/routes/{categories,admin/categories}</code>. Analyse modèle : <code>output/analysis/frontend/Categories_frontend_analysis.md</code>.</li><li><strong>Absent</strong> : <code>api/region.ts</code>, <code>hooks/use-regions.ts</code>, <code>features/regions/</code>, <code>types/region.ts</code>, <code>schemas/region.ts</code>, routes régions.</li><li><strong>Authentification</strong> : toujours absente (jeton admin collé via <code>AdminTokenForm</code>, <code>TODO(Authentification)</code>), aucun <code>authLoader</code>.</li><li><strong>Design</strong> : aucun <code>output/design/regions-screen.json</code> ; styles Shadcn par défaut, mobile-first, unités relatives (pas de <code>w-[..px]</code>).</li></ul><h2 id="specification-api-backend" tabindex="-1">Spécification API Backend <a class="header-anchor" href="#specification-api-backend" aria-label="Permalink to &quot;Spécification API Backend&quot;">​</a></h2><ul><li><strong>OpenAPI Spec</strong> : <code>api-rest-symfony-target/docs/openapi.yaml</code> (chemins avec préfixe <code>/api</code>, <code>servers: http://localhost:8000</code>). <strong>Constat : aucun chemin <code>regions</code> n&#39;y figure encore</strong> (Grep) ; ils seront ajoutés par BACKEND-020.</li><li><strong>Endpoints prévus</strong> : section « Spécification OpenAPI » de <code>output/analysis/backend/Regions_backend_analysis.md</code> (source « prévu BACKEND-0xx »). Le contrat réel devra être revérifié dans <code>openapi.yaml</code> une fois BACKEND-020 traité.</li><li><strong>Authentification</strong> : JWT <code>Authorization: Bearer</code>, <code>ROLE_ADMIN</code> pour <code>/api/admin/**</code>. Lecture publique <code>^/api/regions</code> en <code>PUBLIC_ACCESS</code> (BACKEND-012) : un jeton invalide sur route publique donne 401, d&#39;où <code>skipAuth: true</code> sur les appels publics.</li><li><strong>Format d&#39;erreur</strong> : <code>{ type, code, message, details? }</code> ; violations de validation : <code>details.violations[] = { parameter, message }</code>.</li><li><strong>Collections</strong> : liste admin <code>{ data, meta: { page, count, total } }</code> ; l&#39;arbre public est <code>{ data: [...] }</code> sans <code>meta</code>.</li><li><strong>Schémas</strong> (analyse backend) : <ul><li><code>Region { id (UUID), name, slug, parent (UUID | null), childcount, createdAt, updatedAt | null }</code>. Pas de champ <code>position</code> exposé. <strong>Attention aux différences avec Categories</strong> : clé <code>parent</code> (et non <code>parentId</code>), clé <code>childcount</code> (minuscule, et non <code>childCount</code>), query <code>parent</code> (et non <code>parentId</code>).</li><li><code>RegionTreeNode = Region + children: Region[]</code> (<code>children: []</code> pour une racine sans enfant).</li><li><code>CreateRegionRequest { parent?: string | null, name, slug }</code> (slug <strong>obligatoire</strong>).</li><li><code>UpdateRegionRequest { name, slug, parent? }</code> (name et slug requis comme le formulaire legacy).</li><li><code>GenerateRegionSlugRequest { name }</code> / <code>GenerateRegionSlugResponse { slug }</code>.</li><li><code>MoveRegionRequest { direction: &#39;up&#39; | &#39;down&#39;, parent? }</code> (parent ignoré : non envoyé).</li></ul></li></ul><h2 id="mapping-de-stack-frontend" tabindex="-1">Mapping de Stack Frontend <a class="header-anchor" href="#mapping-de-stack-frontend" aria-label="Permalink to &quot;Mapping de Stack Frontend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect Source</th><th>Équivalent dans Documentation</th><th>Notes</th></tr></thead><tbody><tr><td><code>templates/region-list.php</code> (blocs 3 colonnes, <code>main-category</code>/<code>sub-category</code>, <code>&lt;hr /&gt;</code>)</td><td><code>features/regions/region-tree.tsx</code> + Tailwind <code>grid-cols-1 sm:grid-cols-2 lg:grid-cols-3</code> + <code>Card</code></td><td>Mobile-first (<code>styling.md</code>) ; noms échappés nativement par React (T-04)</td></tr><tr><td><code>Region::get_tree()</code> à chaque requête (<code>common.php:41</code>)</td><td><code>useRegionTree()</code> (React Query, <code>staleTime</code> long)</td><td>Un appel <code>GET /api/regions</code>, invalidé par les mutations admin (E-22 sans objet)</td></tr><tr><td>Liens <code>ad-list.php?region=slug&amp;pageID=0</code> + <code>build_query_string</code></td><td><code>Link</code> + <code>buildRegionSearchPath()</code> (copie des <code>searchParams</code>, retrait <code>id</code>/<code>code</code>/<code>page</code>, <code>region</code> = slug)</td><td>CL-14 ; route de recherche = constante <code>SEARCH_ROUTE</code> existante (<code>/ads</code>, hypothèse)</td></tr><tr><td><code>select-region.php</code> / <code>ad-search-form.php</code> (racines puis enfants préfixés <code>&amp;nbsp;&amp;nbsp;-&amp;nbsp;</code>)</td><td><code>features/regions/region-select.tsx</code> (select natif stylé, <code>valueKey</code> <code>id</code> | <code>slug</code>, option « Tous » optionnelle)</td><td>Composant unique (dette des 5 copies inline, #sec-13) ; pas de pré-sélection par préférence (consommateurs)</td></tr><tr><td>Tableau admin + PEAR Pager (10/page)</td><td><code>features/regions/admin/region-admin-table.tsx</code> + <code>table</code> Shadcn + pagination par <code>?page=</code></td><td><code>meta.total</code> → nombre de pages ; <code>limit=10</code></td></tr><tr><td><code>?parent={id}</code> / <code>pageID{parent}</code></td><td><code>useSearchParams</code> : <code>parent</code>, <code>page</code></td><td>État dans l&#39;URL (<code>features.md</code>)</td></tr><tr><td><code>confirm(&quot;Are you sure to delete?&quot;)</code> + GET <code>?d=</code></td><td><code>AlertDialog</code> + <code>DELETE /api/admin/regions/{id}</code></td><td>T-02, gestion du 409 (E-01)</td></tr><tr><td>Up/Down GET <code>?o=&amp;r=</code></td><td>boutons icône + <code>POST .../move</code></td><td>Toujours actifs (no-op serveur aux extrémités, CL-10)</td></tr><tr><td>Formulaire multi-submit Generate/Create</td><td>React Hook Form + Zod + <code>POST /api/admin/regions/slug</code> pour « Générer »</td><td>Génération <strong>serveur</strong> (RM-12), sans création (Alt 5/6)</td></tr><tr><td><code>&lt;ul class=&#39;errors&#39;&gt;</code></td><td><code>Field</code> en erreur + <code>Alert</code> + toasts sonner</td><td><code>handleFormErrors</code> pour les 422</td></tr><tr><td>Garde admin <code>User::get_id() == 1</code></td><td><code>AdminAccessGate</code> existant + gestion 401/403</td><td>Contrôle réel côté backend (T-03)</td></tr><tr><td>Lien menu « Regions » (<code>page-top.php:41</code>)</td><td><code>NavLink</code> dans <code>AppLayout</code></td><td>Lien actif géré par le routeur (E-21 sans objet)</td></tr><tr><td>Routing scripts</td><td>React Router 7 lazy : <code>/regions</code>, <code>/admin/regions</code>, <code>/admin/regions/new</code>, <code>/admin/regions/:id/edit</code></td><td>Pages suffixées <code>Page</code>, export <code>Component</code> (<code>routing.md</code>)</td></tr></tbody></table><h2 id="differences-avec-categories-ne-pas-copier-aveuglement" tabindex="-1">Différences avec Categories (ne pas copier aveuglément) <a class="header-anchor" href="#differences-avec-categories-ne-pas-copier-aveuglement" aria-label="Permalink to &quot;Différences avec Categories (ne pas copier aveuglément)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sujet</th><th>Categories (frontend existant)</th><th>Regions (spec + backend)</th></tr></thead><tbody><tr><td>Clé du parent / query</td><td><code>parentId</code></td><td><code>parent</code> (réponse, corps, query <code>?parent=</code>)</td></tr><tr><td>Nombre d&#39;enfants</td><td><code>childCount</code></td><td><code>childcount</code></td></tr><tr><td>Slug à la création</td><td>facultatif, généré par le serveur</td><td><strong>obligatoire</strong> ; « Générer » appelle <code>POST /api/admin/regions/slug</code></td></tr><tr><td>Format du slug</td><td><code>^[a-z0-9-]+$</code></td><td><code>^[a-zA-Z0-9_-]+$</code> (#sec-6)</td></tr><tr><td>Unicité du nom</td><td>409 <code>category_name_already_used</code></td><td>aucun contrôle</td></tr><tr><td>Changement de niveau</td><td>promotion/rétrogradation autorisées</td><td><strong>interdites</strong> : select Parent uniquement pour une sous-région ; racine sans select (RM-05)</td></tr><tr><td>Verbe de modification</td><td>PATCH, champs modifiés seuls</td><td>PUT <code>{ name, slug, parent? }</code> complet</td></tr><tr><td>Détail admin</td><td><code>GET /api/admin/categories/{id}</code></td><td><strong>inexistant</strong> : l&#39;édition lit la région dans l&#39;arbre (<code>useRegionTree</code>)</td></tr><tr><td>Up/Down</td><td>désactivés aux extrémités</td><td>toujours actifs (legacy, CL-10)</td></tr><tr><td>Colonnes admin</td><td>Nom, Slug, Sous-catégories, Actions</td><td>Id, Nom, Opérations (legacy)</td></tr><tr><td>Après création</td><td>navigation vers la liste</td><td>reste sur le formulaire, message + lien d&#39;édition, formulaire vidé (#sec-3 Scénario 4)</td></tr><tr><td>Parent inconnu en liste admin</td><td>404</td><td>200 liste vide (« No records. »)</td></tr><tr><td>Parent invalide en écriture</td><td>404 puis 422</td><td>422 avec violation sur <code>parent</code></td></tr></tbody></table><h2 id="exigences-fonctionnelles-frontend" tabindex="-1">Exigences Fonctionnelles Frontend <a class="header-anchor" href="#exigences-fonctionnelles-frontend" aria-label="Permalink to &quot;Exigences Fonctionnelles Frontend&quot;">​</a></h2><h3 id="interface-utilisateur" tabindex="-1">Interface Utilisateur <a class="header-anchor" href="#interface-utilisateur" aria-label="Permalink to &quot;Interface Utilisateur&quot;">​</a></h3><p><strong>Page publique <code>/regions</code></strong> (#sec-3 Scénario 1, #sec-4 Composant 2)</p><ul><li>Titre « Régions » ; grille responsive de blocs : 1 colonne (mobile), 2 (<code>sm</code>), 3 (<code>lg</code>) ; chaque bloc = racine en titre (lien) suivie de ses sous-régions (liens), dans l&#39;ordre de l&#39;API (aucun tri client).</li><li>Lien de chaque libellé : <code>/ads?region={slug}</code> + autres paramètres de la query string courante (ex. <code>category</code>) ; <code>id</code>, <code>code</code>, <code>page</code> non propagés (équivalent de <code>pageID=0</code>).</li><li>Racine sans enfant : affichée seule. Arbre vide : « Aucune région pour le moment. » (équivalent de « Create Regions first! »).</li><li>Pas de comptage d&#39;annonces (n&#39;existe pas en legacy).</li></ul><p><strong>Composant <code>RegionSelect</code></strong> (#sec-3 Scénario 2, #sec-4 Composant 3)</p><ul><li>Options : chaque racine, puis ses sous-régions préfixées de <code> -</code> (indentation) ; valeur = <code>id</code> ou <code>slug</code> selon la prop ; option initiale facultative « Tous » (valeur <code>any</code>) pour la recherche.</li><li>Aucune région : option unique désactivée « Aucune région : créez d&#39;abord des régions. » (message unique, E-12).</li><li>Valeur contrôlée par le parent (<code>value</code>/<code>onChange</code>) ; pré-sélection par préférence utilisateur laissée aux features consommatrices (RM-11, E-07).</li></ul><p><strong>Admin <code>/admin/regions</code></strong> (#sec-3 Scénario 3, #sec-4 Composant 4)</p><ul><li>Niveau racine (défaut) ou sous-régions (<code>?parent={id}</code>). Colonnes : Id (masquée sous <code>sm</code>), Nom, Opérations. Aucune colonne slug (fidélité legacy).</li><li>Opérations : Modifier, Supprimer, Monter, Descendre (icônes + <code>aria-label</code> incluant le nom) ; pour une racine uniquement le lien « Sous-régions (n) » (E-11, n = <code>childcount</code>) ; en niveau enfant, lien « Remonter » vers les racines.</li><li>Bouton « Nouvelle région » (conserve le niveau courant comme parent par défaut).</li><li>Pagination 10/page : liens en haut si <code>total &gt; 10</code>, et en bas ; « Précédent » / « Suivant » + « Page X sur Y ».</li></ul><p><strong>Admin <code>/admin/regions/new</code></strong> (#sec-3 Scénario 4, #sec-4 Composant 5)</p><ul><li>Titre « Créer une région ». Champs : Parent (select « Aucune » + toutes les racines), Nom, Slug (<code>maxLength</code> 50) + bouton « Générer », bouton « Créer ».</li><li>Succès : message vert « Région créée. ( id : {id} ) » avec lien d&#39;édition (nouvel onglet) ; formulaire vidé.</li></ul><p><strong>Admin <code>/admin/regions/:id/edit</code></strong> (#sec-3 Scénario 5, #sec-4 Composant 6)</p><ul><li>Titre « Modifier la région ( id : {id} ) ». Champs : Nom, Slug (<code>maxLength</code> 50, pas de bouton Générer, E-18), Parent (select des racines <strong>uniquement si la région est une sous-région</strong>). Boutons « Modifier » et « Réinitialiser » (confirmation « Voulez-vous vraiment réinitialiser le formulaire ? » puis retour aux valeurs chargées).</li><li>Succès : « Région modifiée. ». Id inexistant : « Cette région n&#39;existe pas. » + lien vers la liste.</li></ul><h3 id="interactions-utilisateur" tabindex="-1">Interactions Utilisateur <a class="header-anchor" href="#interactions-utilisateur" aria-label="Permalink to &quot;Interactions Utilisateur&quot;">​</a></h3><ul><li>Clic sur une région (public) : navigation <code>/ads?region={slug}</code> + filtres conservés.</li><li>Clic « Sous-régions (n) » : <code>?parent={id}</code> (page réinitialisée) ; « Remonter » : retour aux racines.</li><li>Monter/Descendre : <code>POST /move</code> ; liste rafraîchie ; boutons désactivés uniquement pendant la mutation de la ligne.</li><li>Supprimer : <code>AlertDialog</code> « Voulez-vous vraiment supprimer ? » (nom de la région) puis <code>DELETE</code> ; annulation = rien ; 204 → toast ; 409 → message dans la boîte de dialogue.</li><li>« Générer » : <code>POST /api/admin/regions/slug</code> avec le nom saisi → slug placé dans le champ Slug, aucune création.</li><li>Soumission : validation Zod côté client puis appel API ; erreurs serveur mappées sur les champs.</li></ul><h3 id="etats-de-l-application" tabindex="-1">États de l&#39;Application <a class="header-anchor" href="#etats-de-l-application" aria-label="Permalink to &quot;États de l&#39;Application&quot;">​</a></h3><ul><li><strong>Loading</strong> : <code>Skeleton</code> (arbre, tableau, formulaire d&#39;édition tant que l&#39;arbre charge) ; boutons <code>disabled</code> + <code>Spinner</code> pendant les mutations.</li><li><strong>Error</strong> : <code>Alert</code> destructive + « Réessayer » en lecture ; 401 → formulaire de jeton ; 403 → « Droits administrateur requis » (<code>AdminErrorAlert</code> existant) ; réseau/500 → <code>handleApiError</code>.</li><li><strong>Empty</strong> : public « Aucune région pour le moment. » ; admin <code>Empty</code> « Aucun enregistrement. » (« No records. ») ; select : message unique.</li><li><strong>Success</strong> : toasts sonner pour modification/suppression ; message inline pour la création ; pas de toast au déplacement.</li></ul><p><strong>Mapping des erreurs de mutation</strong></p><table tabindex="0"><thead><tr><th>HTTP / code</th><th>Contexte</th><th>Rendu</th></tr></thead><tbody><tr><td>422 <code>validation_error</code>, <code>parameter</code> = <code>name</code> / <code>slug</code></td><td>création/édition</td><td>erreur sur le champ via <code>handleFormErrors</code> (messages legacy : « The name field is required ! », « Invalid name! », « The slug field is required ! », « Invalid slug! », messages de longueur)</td></tr><tr><td>422 <code>validation_error</code>, <code>parameter</code> = <code>parent</code></td><td>création/édition</td><td>erreur sur le champ Parent (<code>region_parent_not_found</code>, <code>region_parent_not_root</code>, <code>region_parent_is_self</code>)</td></tr><tr><td>422 sur <code>generate slug</code></td><td>bouton Générer</td><td>erreur « Invalid name! » sur le champ Nom, aucune création (Alt 5)</td></tr><tr><td>409 <code>region_slug_already_used</code></td><td>création/édition</td><td>erreur sur Slug : « Ce slug est déjà utilisé. » (E-03)</td></tr><tr><td>409 <code>region_has_children</code></td><td>suppression</td><td>message dans la boîte de dialogue : « Cette région contient des sous-régions : supprimez-les ou déplacez-les d&#39;abord. » (E-01)</td></tr><tr><td>404 <code>region_not_found</code></td><td>édition/suppression/déplacement</td><td>toast « Région introuvable », invalidation de la liste</td></tr><tr><td>400 <code>invalid_request_body</code></td><td>toutes</td><td><code>handleApiError</code> générique</td></tr><tr><td>401 / 403</td><td>routes admin</td><td><code>AdminErrorAlert</code></td></tr></tbody></table><h2 id="endpoints-backend-utilises" tabindex="-1">Endpoints Backend Utilisés <a class="header-anchor" href="#endpoints-backend-utilises" aria-label="Permalink to &quot;Endpoints Backend Utilisés&quot;">​</a></h2><p>Aucun n&#39;est encore dans <code>OPENAPI_SPEC</code> : tous sont « prévu BACKEND-0xx ».</p><h3 id="public-sans-authentification-skipauth-true" tabindex="-1">Public (sans authentification, <code>skipAuth: true</code>) <a class="header-anchor" href="#public-sans-authentification-skipauth-true" aria-label="Permalink to &quot;Public (sans authentification, `skipAuth: true`)&quot;">​</a></h3><ul><li><code>GET /api/regions</code> (<code>getRegionTree</code>, prévu BACKEND-013) : arbre <code>{ data: RegionTreeNode[] }</code> ; alimente la page publique, <code>RegionSelect</code>, les selects Parent et la lecture de la région à éditer.</li></ul><blockquote><p><code>GET /api/regions/by-slug/{slug}</code> (<code>getRegionBySlug</code>, prévu BACKEND-013) <strong>n&#39;est pas consommé</strong> ici (contrat destiné à la feature Recherche).</p></blockquote><h3 id="administration-jwt-bearer-role-admin" tabindex="-1">Administration (JWT Bearer, <code>ROLE_ADMIN</code>) <a class="header-anchor" href="#administration-jwt-bearer-role-admin" aria-label="Permalink to &quot;Administration (JWT Bearer, `ROLE_ADMIN`)&quot;">​</a></h3><ul><li><code>GET /api/admin/regions?parent&amp;page&amp;limit</code> (<code>listAdminRegions</code>, prévu BACKEND-014) : liste d&#39;un niveau <code>{ data: Region[], meta }</code>.</li><li><code>POST /api/admin/regions</code> (<code>createRegion</code>, prévu BACKEND-015) : 201.</li><li><code>POST /api/admin/regions/slug</code> (<code>generateRegionSlug</code>, prévu BACKEND-016) : <code>{ slug }</code>.</li><li><code>PUT /api/admin/regions/{id}</code> (<code>updateRegion</code>, prévu BACKEND-017) : 200.</li><li><code>DELETE /api/admin/regions/{id}</code> (<code>deleteRegion</code>, prévu BACKEND-018) : 204 ; 409 si sous-régions.</li><li><code>POST /api/admin/regions/{id}/move</code> (<code>moveRegion</code>, prévu BACKEND-019) : <code>{ direction }</code>, 200 sans effet aux extrémités.</li></ul><h2 id="liste-des-taches-frontend" tabindex="-1">Liste des Tâches Frontend <a class="header-anchor" href="#liste-des-taches-frontend" aria-label="Permalink to &quot;Liste des Tâches Frontend&quot;">​</a></h2><h4 id="frontend-001-reutiliser-le-client-http-et-definir-les-types-types-region-ts" tabindex="-1">FRONTEND-001 : Réutiliser le client HTTP et définir les types <code>types/region.ts</code> <a class="header-anchor" href="#frontend-001-reutiliser-le-client-http-et-definir-les-types-types-region-ts" aria-label="Permalink to &quot;FRONTEND-001 : Réutiliser le client HTTP et définir les types `types/region.ts`&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Setup</li><li><strong>Description</strong> : Le client HTTP existe déjà (<code>src/lib/api-client.ts</code>, base = origine seule, chemins <code>/api/...</code>, <code>skipAuth</code>, intercepteurs 401/403 déjà corrigés par la feature Categories) : <strong>le réutiliser sans l&#39;écraser</strong>. Ajouter uniquement les types TypeScript de la feature, dérivés de la section OpenAPI prévue.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : n/a (infrastructure) ; contexte <code>php-legacy/admin/include/db-region.php</code>.</li><li><strong>Vérifications préalables</strong> : relire <code>lib/api-client.ts</code> et <code>types/api.ts</code> ; ne rien modifier s&#39;ils sont conformes (<code>PaginatedResponse</code>, <code>skipAuth</code>, absence de <code>/api/api</code>).</li><li><strong>Implémentation selon la documentation</strong> (<code>.claude/skills/front-app-conventions/references/api-integration.md</code>) : <ul><li><code>src/types/region.ts</code> : <code>Region</code> (<code>id</code>, <code>name</code>, <code>slug</code>, <code>parent: string | null</code>, <code>childcount</code>, <code>createdAt</code>, <code>updatedAt: string | null</code>), <code>RegionTreeNode</code> (<code>Region</code> + <code>children: Region[]</code>), <code>RegionTreeResponse</code> (<code>{ data: RegionTreeNode[] }</code>), <code>CreateRegionRequest</code>, <code>UpdateRegionRequest</code>, <code>GenerateRegionSlugRequest/Response</code>, <code>MoveRegionRequest</code>, <code>AdminRegionListParams</code> (<code>parent?</code>, <code>page?</code>, <code>limit?</code>) ; réutiliser <code>MoveDirection</code> de <code>types/category.ts</code> (ou le déplacer dans <code>types/api.ts</code> sans casser Categories). <code>import type</code>, pas de <code>any</code>.</li><li>Commentaire d&#39;en-tête : « Types dérivés de la section OpenAPI de Regions_backend_analysis.md (BACKEND-020 : revérifier dans <code>openapi.yaml</code> ».</li></ul></li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Aucun fichier du client HTTP modifié sans nécessité</li><li>Types conformes à la spec backend (clés <code>parent</code>, <code>childcount</code>)</li><li><code>npm run typecheck</code> passe</li></ul></li></ul></li></ul><h4 id="frontend-002-schemas-zod-messages-d-erreur-et-utilitaire-de-lien-de-recherche" tabindex="-1">FRONTEND-002 : Schémas Zod, messages d&#39;erreur et utilitaire de lien de recherche <a class="header-anchor" href="#frontend-002-schemas-zod-messages-d-erreur-et-utilitaire-de-lien-de-recherche" aria-label="Permalink to &quot;FRONTEND-002 : Schémas Zod, messages d&#39;erreur et utilitaire de lien de recherche&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Types / Logique</li><li><strong>Description</strong> : Validation des formulaires région (règles legacy #sec-6), table de messages par <code>code</code> backend, construction du lien vers la recherche en conservant les filtres.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-001</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : <code>php-legacy/admin/region-create.php:28-46</code>, <code>region-edit.php:50-60</code>, <code>templates/region-list.php:19,27</code>, <code>admin/include/common.php:203-218</code>.</li><li><strong>Implémentation actuelle (Source)</strong> : nom requis après <code>trim</code> puis <code>/^[\\w- ]*$/u</code> (« The name field is required ! » / « Invalid name! ») ; slug requis puis <code>/^[a-zA-Z0-9_-]*$/</code> (« The slug field is required ! » / « Invalid slug! ») ; aucune validation de longueur (corrigée par E-13/E-14) ; liens recopiant les GET courants.</li><li><strong>Implémentation selon la documentation</strong> (<code>code-standards.md</code>, <code>features.md</code>) : <ul><li><code>src/schemas/region.ts</code> : <code>regionFormSchema</code> : <code>name</code> <code>trim</code>, requis, regex <code>/^[\\p{L}\\p{N}_\\- ]+$/u</code> (E-15 : apostrophe, parenthèses, point, virgule refusés), max 50 ; <code>slug</code> <code>trim</code>, requis, regex <code>/^[a-zA-Z0-9_-]+$/</code>, max 50 ; <code>parent</code> <code>string | null</code>. Messages = équivalents français des messages legacy (« Le nom est obligatoire. », « Nom invalide. », « Le slug est obligatoire. », « Slug invalide. », « Le nom est trop long (50 caractères maximum). », « Le slug est trop long (50 caractères maximum). »). Un seul message par champ vide (pas de doublon <code>required</code> + <code>regex</code>).</li><li><code>src/lib/region-error-messages.ts</code> : <code>getRegionErrorMessage(code)</code> : <code>region_slug_already_used</code>, <code>region_has_children</code>, <code>region_not_found</code>, <code>region_parent_not_found</code>, <code>region_parent_not_root</code>, <code>region_parent_is_self</code>.</li><li><code>src/lib/region-links.ts</code> : <code>buildRegionSearchPath(slug, currentParams)</code> (réutilise <code>SEARCH_ROUTE</code> de <code>category-links.ts</code>, retire <code>id</code>, <code>code</code>, <code>page</code>, définit <code>region</code>) ; <code>regionLevelPath(parent, page)</code> → <code>/admin/regions?parent=…&amp;page=…</code>.</li></ul></li><li><strong>Tests (Test First)</strong> : <code>tests/unit/schemas/region.test.ts</code> (nom vide/espaces seuls KO, <code>Côte d&#39;Azur</code> KO, <code>Île de France</code> OK, 50 OK, 51 KO ; slug avec espace/accent/<code>/</code> KO, <code>a_B-1</code> OK, vide KO), <code>tests/unit/lib/region-links.test.ts</code> (conserve <code>category</code>, remplace un <code>region</code> existant, retire <code>id</code>/<code>code</code>/<code>page</code>), <code>tests/unit/lib/region-error-messages.test.ts</code>.</li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Règles identiques au legacy (#sec-6, E-13, E-14, E-15)</li><li>Filtres de la query conservés (CL-14)</li><li>Imports <code>@/</code>, pas de <code>any</code></li></ul></li></ul></li></ul><h4 id="frontend-003-creer-les-fixtures-et-handlers-msw-des-regions" tabindex="-1">FRONTEND-003 : Créer les fixtures et handlers MSW des régions <a class="header-anchor" href="#frontend-003-creer-les-fixtures-et-handlers-msw-des-regions" aria-label="Permalink to &quot;FRONTEND-003 : Créer les fixtures et handlers MSW des régions&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Tests (infrastructure)</li><li><strong>Description</strong> : Jeu de données et handlers MSW stateful couvrant les 7 endpoints consommés, enregistrés dans <code>tests/mocks/handlers.ts</code>.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-001, FRONTEND-002</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : <code>php-legacy/db-sample.sql:68-70</code> ; fixtures backend BACKEND-003.</li><li><strong>Implémentation selon la documentation</strong> (<code>.claude/skills/front-testing-conventions/references/mocking-strategies.md</code>) : <ul><li><code>tests/mocks/region-fixtures.ts</code> : au moins 3 racines dont une sans enfant, une racine avec 3 sous-régions, « Dummy City » &gt; « Sub City » ; UUID stables ; fabrique <code>buildRegion()</code>.</li><li><code>tests/mocks/region-handlers.ts</code> : <code>GET /api/regions</code> (<code>{ data }</code>), <code>GET/POST /api/admin/regions</code> (<code>createApiUrl(&#39;/api/admin/regions&#39;)</code>, la base du projet est l&#39;origine : suivre la convention de <code>category-handlers.ts</code>), <code>POST /api/admin/regions/slug</code>, <code>PUT/DELETE /api/admin/regions/:id</code>, <code>POST /api/admin/regions/:id/move</code> ; handlers admin exigeant <code>Authorization: Bearer</code> (401 sinon) ; pagination <code>page</code>/<code>limit</code> avec <code>meta { page, count, total }</code> ; liste d&#39;un parent inconnu = 200 vide ; 409 <code>region_has_children</code> et <code>region_slug_already_used</code> ; 422 avec <code>details.violations</code>.</li><li>Réinitialisation du store en mémoire avant chaque test (comme les catégories dans <code>tests/setup.ts</code>).</li></ul></li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Formes de réponse conformes à l&#39;analyse backend (clés <code>parent</code>, <code>childcount</code>, <code>children</code>)</li><li>Handlers surchargeables par test (<code>mockServer.use</code>)</li><li>Aucune requête non mockée dans les tests de la feature</li></ul></li></ul></li></ul><h4 id="frontend-004-creer-la-couche-api-api-region-ts" tabindex="-1">FRONTEND-004 : Créer la couche API <code>api/region.ts</code> <a class="header-anchor" href="#frontend-004-creer-la-couche-api-api-region-ts" aria-label="Permalink to &quot;FRONTEND-004 : Créer la couche API `api/region.ts`&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - API</li><li><strong>Description</strong> : Objet <code>regionApi</code> d&#39;appels directs via <code>apiClient</code> (un fichier par ressource).</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-001, FRONTEND-003</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : scripts HTML admin (aucune API).</li><li><strong>Implémentation selon la documentation</strong> (<code>api-integration.md</code>, modèle <code>api/category.ts</code>) : <ul><li><code>getTree()</code> : <code>GET /api/regions</code>, <code>skipAuth: true</code>, retourne <code>data.data</code>.</li><li><code>adminList({ parent, page = 1, limit = 10 })</code> : <code>GET /api/admin/regions</code> ; omettre <code>parent</code> s&#39;il est vide ; retourne <code>PaginatedResponse&lt;Region&gt;</code>.</li><li><code>create(dto)</code> : <code>POST /api/admin/regions</code> ; <code>parent</code> omis si <code>null</code>/absent (racine).</li><li><code>generateSlug(name)</code> : <code>POST /api/admin/regions/slug</code> → <code>{ slug }</code>.</li><li><code>update(id, dto)</code> : <code>PUT /api/admin/regions/{id}</code> avec <code>{ name, slug }</code> et <code>parent</code> seulement s&#39;il est fourni.</li><li><code>remove(id)</code> : <code>DELETE</code>. <code>move(id, direction)</code> : <code>POST .../move</code> avec <code>{ direction }</code> seul.</li><li>Pas d&#39;adaptateur : types de réponse = schémas backend. <code>getBySlug</code> non implémenté (hors périmètre).</li></ul></li><li><strong>Tests (Test First)</strong> : <code>tests/unit/api/region.test.ts</code> (MSW) : URL et méthode de chaque appel, <code>Authorization</code> présent en admin et absent sur <code>getTree</code>, <code>parent</code> omis pour une racine, <code>parent</code> absent de <code>move</code>, <code>ApiError</code> avec <code>status</code>/<code>data</code> sur 409/422.</li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>7 appels conformes aux <code>operationId</code> prévus</li><li>Aucune URL ne contient <code>/api/api</code></li></ul></li></ul></li></ul><h4 id="frontend-005-creer-les-hooks-react-query-hooks-use-regions-ts" tabindex="-1">FRONTEND-005 : Créer les hooks React Query <code>hooks/use-regions.ts</code> <a class="header-anchor" href="#frontend-005-creer-les-hooks-react-query-hooks-use-regions-ts" aria-label="Permalink to &quot;FRONTEND-005 : Créer les hooks React Query `hooks/use-regions.ts`&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Hook</li><li><strong>Description</strong> : Query keys hiérarchiques, lectures (arbre, liste d&#39;un niveau) et mutations (création, génération de slug, modification, suppression, déplacement) avec invalidation.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-004</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : arbre rechargé à chaque requête (<code>common.php:41</code>) remplacé par un cache.</li><li><strong>Implémentation selon la documentation</strong> (<code>.claude/skills/front-app-conventions/references/state-management.md</code>) : <ul><li><code>regionKeys = { all: [&#39;regions&#39;], tree: () =&gt; [...all, &#39;tree&#39;], lists: () =&gt; [...all, &#39;list&#39;], list: (params) =&gt; [...all, &#39;list&#39;, params] }</code>.</li><li><code>useRegionTree()</code> (<code>staleTime</code> 5 min), <code>useAdminRegions({ parent, page })</code> (<code>placeholderData: keepPreviousData</code>, <code>retry: false</code>), <code>useRegion(id)</code> : dérivé de <code>useRegionTree()</code> par recherche de l&#39;id parmi racines et enfants (pas d&#39;endpoint de détail) ; retourne <code>undefined</code> si absent une fois chargé.</li><li><code>useCreateRegion()</code>, <code>useUpdateRegion()</code>, <code>useDeleteRegion()</code>, <code>useMoveRegion()</code> : <code>onSuccess</code> → <code>invalidateQueries({ queryKey: regionKeys.all })</code>. <code>useGenerateRegionSlug()</code> : mutation sans invalidation.</li><li>Pas de toast dans les hooks ; pas de Zustand.</li></ul></li><li><strong>Tests (Test First)</strong> : <code>tests/unit/hooks/use-regions.test.tsx</code> : arbre chargé, arbre vide, <code>useRegion</code> trouve une sous-région, <code>useRegion</code> retourne <code>undefined</code> pour un id inconnu, invalidation après create/move/delete, liste d&#39;un parent change avec le paramètre, 401 exposé en <code>ApiError</code>, génération de slug sans invalidation.</li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Toute mutation d&#39;écriture invalide <code>regionKeys.all</code></li><li><code>ApiError</code> exposée telle quelle (<code>error.status</code>, <code>error.data.code</code>)</li></ul></li></ul></li></ul><h4 id="frontend-006-generaliser-adminbreadcrumb-pour-les-ecrans-regions" tabindex="-1">FRONTEND-006 : Généraliser <code>AdminBreadcrumb</code> pour les écrans régions <a class="header-anchor" href="#frontend-006-generaliser-adminbreadcrumb-pour-les-ecrans-regions" aria-label="Permalink to &quot;FRONTEND-006 : Généraliser `AdminBreadcrumb` pour les écrans régions&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Composant</li><li><strong>Description</strong> : <code>AdminBreadcrumb</code> code en dur « Catégories » et <code>/admin/categories</code>. Le rendre paramétrable sans changer le rendu des pages catégories.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-001</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : n/a (réutilisation cible) ; fichier <code>app-react-target/src/features/admin/admin-breadcrumb.tsx</code>.</li><li><strong>Implémentation</strong> : ajouter les props <code>section?: string</code> (défaut « Catégories ») et <code>sectionPath?: string</code> (défaut <code>/admin/categories</code>) ; les pages catégories existantes restent inchangées. Vérifier par lecture que <code>admin-access-gate.tsx</code> et <code>admin-error-alert.tsx</code> ne dépendent d&#39;aucune clé catégorie (Grep <code>categoryKeys</code>) ; sinon, les rendre génériques.</li><li><strong>Tests</strong> : étendre le test existant d&#39;<code>AdminBreadcrumb</code> si présent (sinon test unitaire minimal : « Régions » + lien <code>/admin/regions</code> quand <code>current</code> est fourni).</li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Tests Categories toujours verts</li><li>Fil d&#39;Ariane « Administration &gt; Régions &gt; {page} » possible</li></ul></li></ul></li></ul><h4 id="frontend-007-feature-publique-regiontree-et-page-regions" tabindex="-1">FRONTEND-007 : Feature publique <code>RegionTree</code> et page <code>/regions</code> <a class="header-anchor" href="#frontend-007-feature-publique-regiontree-et-page-regions" aria-label="Permalink to &quot;FRONTEND-007 : Feature publique `RegionTree` et page `/regions`&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Feature + Page</li><li><strong>Description</strong> : Affichage responsive de l&#39;arbre des régions avec liens vers la recherche et états loading/error/empty.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-002, FRONTEND-005</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : <code>php-legacy/region-list.php</code>, <code>php-legacy/templates/region-list.php</code> (blocs de 3 colonnes, <code>main-category</code>/<code>sub-category</code>, <code>&lt;hr /&gt;</code>, « Create Regions first! »).</li><li><strong>Implémentation actuelle (Source)</strong> : racines par blocs de 3 colonnes, sous-régions sous la racine ; liens <code>ad-list.php?region={slug}&amp;pageID=0</code> + GET courants ; racine sans enfant affichée seule.</li><li><strong>Implémentation selon la documentation</strong> (<code>features.md</code>, <code>routing.md</code>, <code>styling.md</code>) : <ul><li><code>src/features/regions/region-tree.tsx</code> : <code>useRegionTree()</code> + <code>useSearchParams()</code> ; grille <code>grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3</code> ; <code>Card</code> par racine ; <code>Link to={buildRegionSearchPath(slug, searchParams)}</code> ; listes <code>ul</code>/<code>li</code> ; ordre de l&#39;API.</li><li><code>src/app/routes/regions/regions-list.tsx</code> : <code>RegionsListPage</code> (HTML minimal, <code>h1</code> « Régions »), export <code>Component</code>.</li><li>États : <code>Skeleton</code>, <code>Alert</code> + « Réessayer », <code>Empty</code> « Aucune région pour le moment. ».</li><li>Accessibilité : <code>section</code> avec <code>aria-labelledby</code>, focus visible.</li></ul></li><li><strong>Tests (Test First)</strong> : <code>tests/unit/features/regions/region-tree.test.tsx</code> : <code>should render roots and sub regions in api order</code>, <code>should link to search with region slug</code>, <code>should keep category filter in links when query string has category</code>, <code>should drop id code and page params from links</code>, <code>should render root without children</code>, <code>should show empty state when no regions</code>, <code>should show error alert and retry when request fails</code>, <code>should escape region names</code>.</li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Arbre fidèle à l&#39;ordre de l&#39;API (#sec-3 Scénario 1)</li><li>Colonnes 1/2/3 mobile-first, sans pixels codés en dur</li><li>Appel public sans en-tête <code>Authorization</code></li><li>Pas de comptage d&#39;annonces</li></ul></li></ul></li></ul><h4 id="frontend-008-composant-partage-regionselect" tabindex="-1">FRONTEND-008 : Composant partagé <code>RegionSelect</code> <a class="header-anchor" href="#frontend-008-composant-partage-regionselect" aria-label="Permalink to &quot;FRONTEND-008 : Composant partagé `RegionSelect`&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Composant</li><li><strong>Description</strong> : Liste déroulante de région réutilisable par les features consommatrices (recherche, dépôt, modification, profil, selects Parent admin).</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-005</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : <code>php-legacy/templates/parts/select-region.php</code>, <code>templates/forms/ad-search-form.php:31-45</code>, copies inline <code>admin/ad-create.php:204-220</code>, <code>admin/user-edit.php:180-198</code>.</li><li><strong>Implémentation actuelle (Source)</strong> : racines puis sous-régions préfixées <code>&amp;nbsp;&amp;nbsp;-&amp;nbsp;</code> ; valeur <code>id</code> ou <code>slug</code> ; option « Any » (<code>any</code>) en recherche ; messages de select vide incohérents (E-12).</li><li><strong>Implémentation selon la documentation</strong> : <ul><li><code>src/features/regions/region-select.tsx</code> : props <code>{ id, value, onChange, valueKey?: &#39;id&#39; | &#39;slug&#39;, allowAny?: boolean, rootsOnly?: boolean, excludeId?: string, disabled?, &#39;aria-invalid&#39;?, &#39;aria-describedby&#39;? }</code> ; données via <code>useRegionTree()</code> ; <code>&lt;select&gt;</code> natif stylé Tailwind (même choix que <code>category-parent-field.tsx</code>, accessible et testable sous jsdom) ; sous-régions préfixées d&#39;un tiret et d&#39;un retrait.</li><li><code>rootsOnly</code> sert au champ Parent (création/édition) ; <code>allowAny</code> ajoute « Tous » (valeur <code>any</code>).</li><li>Aucune région : option unique désactivée au message unique « Aucune région : créez d&#39;abord des régions. » (E-12).</li><li>Pas de pré-sélection par préférence utilisateur (RM-11/E-07 : consommateurs).</li></ul></li><li><strong>Tests (Test First)</strong> : <code>tests/unit/features/regions/region-select.test.tsx</code> : <code>should list roots then indented sub regions</code>, <code>should use id as option value by default</code>, <code>should use slug as option value when valueKey is slug</code>, <code>should show any option when allowAny</code>, <code>should list only roots when rootsOnly</code>, <code>should exclude region when excludeId</code>, <code>should show single message when no regions</code>, <code>should call onChange with selected value</code>.</li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Un seul composant pour les cas id/slug (réponse à la dette des 5 copies, #sec-13)</li><li>Accessible : label associé via <code>id</code>, <code>aria-invalid</code> relayé</li></ul></li></ul></li></ul><h4 id="frontend-009-feature-admin-regionadmintable-liste-par-niveau-pagination-deplacement-suppression" tabindex="-1">FRONTEND-009 : Feature admin <code>RegionAdminTable</code> (liste par niveau, pagination, déplacement, suppression) <a class="header-anchor" href="#frontend-009-feature-admin-regionadmintable-liste-par-niveau-pagination-deplacement-suppression" aria-label="Permalink to &quot;FRONTEND-009 : Feature admin `RegionAdminTable` (liste par niveau, pagination, déplacement, suppression)&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Feature</li><li><strong>Description</strong> : Tableau d&#39;administration d&#39;un niveau de l&#39;arbre, pagination pilotée par l&#39;URL, déplacement haut/bas, navigation vers les sous-régions et suppression confirmée.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-005, FRONTEND-006</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : <code>php-legacy/admin/region-list.php</code> (10/page, Id/Name/Operations, Edit/Delete/Up/Down/« Subcategories(n) », « No records. », lien « Up »).</li><li><strong>Implémentation actuelle (Source)</strong> : actions en GET, Up/Down toujours affichés, suppression sans contrôle, libellé « Subcategories(n) » copié de Catégories (E-11), pagination en haut si <code>tct &gt; rpp</code> et en bas.</li><li><strong>Implémentation selon la documentation</strong> (<code>features.md</code>, modèle <code>category-admin-table.tsx</code>) : <ul><li><code>src/features/regions/admin/region-admin-table.tsx</code> : lit <code>parent</code> et <code>page</code> (défaut 1, invalide → 1) via <code>useSearchParams</code> ; <code>useAdminRegions({ parent, page })</code> ; <code>Table</code> dans <code>overflow-x-auto</code> ; colonne Id <code>hidden sm:table-cell</code> ; colonne Opérations en boutons icône (<code>Pencil</code>, <code>Trash2</code>, <code>ArrowUp</code>, <code>ArrowDown</code>) à zones tactiles ≥ 44 px sous <code>sm</code>, <code>aria-label</code> incluant le nom ; lien « Sous-régions ({childcount}) » seulement pour une racine (<code>parent === null</code>) vers <code>?parent={id}</code> ; lien « Remonter » si un parent est sélectionné.</li><li><strong>Up/Down toujours actifs</strong> (CL-10), désactivés seulement pendant la mutation de la ligne.</li><li>Suppression : <code>AlertDialog</code> (nom de la région) → <code>useDeleteRegion</code> ; 204 → toast « Région supprimée » ; si la page devient vide et <code>page &gt; 1</code> → page précédente ; 409 <code>region_has_children</code> → message E-01 dans la boîte de dialogue ; 404 → toast + rafraîchissement ; annulation = aucune requête.</li><li>Liens Modifier : <code>/admin/regions/{id}/edit</code> en conservant <code>parent</code> et <code>page</code> d&#39;origine.</li><li>Titre du niveau : si <code>parent</code> est défini, nom de la racine lu dans <code>useRegion(parent)</code> (« Sous-régions de {nom} ») ; parent inconnu → liste vide « Aucun enregistrement. » (le backend répond 200).</li><li>Pagination <code>Button</code> « Précédent »/« Suivant » + « Page X sur Y » (<code>ceil(total / 10)</code>), affichée en haut et en bas si <code>total &gt; 10</code>.</li><li>Erreurs de lecture via <code>AdminErrorAlert</code> ; vide via <code>Empty</code> + action « Nouvelle région ».</li></ul></li><li><strong>Tests (Test First)</strong> : <code>tests/unit/features/regions/admin/region-admin-table.test.tsx</code> : <code>should list roots with child count</code>, <code>should list sub regions when parent is set</code>, <code>should show sub regions link only for roots</code>, <code>should keep up and down enabled on first and last rows</code>, <code>should call move endpoint with up direction when clicking up</code>, <code>should refresh list after move</code>, <code>should ask confirmation before deleting</code>, <code>should not delete when cancelling</code>, <code>should delete and show success when confirming</code>, <code>should show children conflict message when delete returns 409</code>, <code>should go to previous page when last item of page is deleted</code>, <code>should paginate with page param</code>, <code>should hide pagination when total fits one page</code>, <code>should show empty state when no records</code>, <code>should show forbidden message when api returns 403</code>, <code>should show token form when api returns 401</code>.</li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Aucune mutation en GET ; suppression uniquement après confirmation (#sec-3 Scénario 6)</li><li>Libellé « Sous-régions (n) » (E-11), colonnes Id/Nom/Opérations (#sec-4 Composant 4)</li><li>Pagination par 10 conforme à <code>meta.total</code>, état dans l&#39;URL</li><li>Noms rendus en texte, tableau utilisable sur mobile</li></ul></li></ul></li></ul><h4 id="frontend-010-feature-admin-regionform-creation-et-modification" tabindex="-1">FRONTEND-010 : Feature admin <code>RegionForm</code> (création et modification) <a class="header-anchor" href="#frontend-010-feature-admin-regionform-creation-et-modification" aria-label="Permalink to &quot;FRONTEND-010 : Feature admin `RegionForm` (création et modification)&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Feature</li><li><strong>Description</strong> : Formulaire React Hook Form + Zod pour créer ou modifier une région : slug obligatoire, bouton « Générer » (création uniquement), parent restreint aux sous-régions en édition (RM-05), mapping des erreurs serveur.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-002, FRONTEND-005, FRONTEND-008</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : <code>php-legacy/admin/region-create.php</code> (Parent, Name, Slug+Generate, Create), <code>php-legacy/admin/region-edit.php</code> (Name, Slug, Parent si sous-région, Modify/Reset).</li><li><strong>Implémentation actuelle (Source)</strong> : validation serveur seulement ; « Generate » soumet le formulaire et réaffiche le slug sans créer ; après création : message « Region created succesfuly. ( id: {id} ) » + lien d&#39;édition en nouvel onglet, formulaire vidé ; édition : parent modifié seulement si ancien et nouveau parent &gt; 0 ; Reset avec <code>confirm</code>.</li><li><strong>Implémentation selon la documentation</strong> (<code>features.md</code>, <code>state-management.md</code>) : <ul><li><code>src/features/regions/admin/region-form.tsx</code> : props <code>{ region?: Region; defaultParent?: string | null; onSuccess?: (region: Region) =&gt; void; onCancel?: () =&gt; void }</code> ; <code>useForm</code> + <code>zodResolver(regionFormSchema)</code>.</li><li><strong>Création</strong> : champ Parent via <code>RegionSelect rootsOnly</code> avec option « Aucune » (valeur vide → <code>parent</code> omis) ; Nom ; Slug (<code>maxLength</code> 50) + bouton « Générer » → <code>useGenerateRegionSlug().mutateAsync(name)</code> puis <code>setValue(&#39;slug&#39;, slug)</code> ; nom vide/invalide → erreur « Nom invalide » sur Nom sans appel/avec 422 mappé (Alt 5) ; slug retourné vide (nom non translittérable, CL-13) laissé vide : l&#39;erreur « Le slug est obligatoire. » apparaît à la soumission. Succès : <code>Alert</code> « Région créée. ( id : {id} ) » + lien « Modifier » (<code>target=&quot;_blank&quot;</code>, <code>rel=&quot;noopener noreferrer&quot;</code>) ; <code>form.reset()</code> complet.</li><li><strong>Modification</strong> : Nom ; Slug <strong>sans</strong> bouton Générer (E-18) ; select Parent affiché <strong>uniquement si <code>region.parent !== null</code></strong>, liste des racines, sans option « Aucune » (promotion impossible) ; une racine n&#39;a aucun select ni <code>parent</code> dans le corps. Soumission <code>PUT { name, slug, parent? }</code> (parent envoyé seulement pour une sous-région). « Réinitialiser » : <code>AlertDialog</code> « Voulez-vous vraiment réinitialiser le formulaire ? » puis <code>form.reset(valeursChargées)</code>. Succès : toast « Région modifiée. », <code>onSuccess</code>.</li><li>Erreurs : 422 → <code>handleFormErrors(error, form.setError)</code> (inclut <code>parent</code>) ; 409 <code>region_slug_already_used</code> → <code>setError(&#39;slug&#39;)</code> ; 404 → toast + <code>onCancel</code> ; 401/403 → <code>AdminErrorAlert</code>. Valeurs saisies conservées en cas d&#39;erreur.</li><li>Boutons : Créer/Modifier (<code>disabled</code> + <code>Spinner</code> pendant <code>isPending</code>), Réinitialiser (édition), Annuler.</li></ul></li><li><strong>Tests (Test First)</strong> : <code>tests/unit/features/regions/admin/region-form.test.tsx</code> (MSW + user-event) : <code>should show required error when name is empty</code>, <code>should reject invalid name characters</code>, <code>should show required error when slug is empty</code>, <code>should reject invalid slug characters</code>, <code>should generate slug from name when clicking generate</code>, <code>should not create region when clicking generate</code>, <code>should show name error when generate fails with invalid name</code>, <code>should create root region without parent</code>, <code>should create sub region with selected parent</code>, <code>should show success message with edit link and clear form after create</code>, <code>should show slug conflict on slug field when api returns 409</code>, <code>should map 422 parent violation to parent field</code>, <code>should hide parent select and generate button when editing a root</code>, <code>should show parent select without none option when editing a sub region</code>, <code>should send put with parent for sub region</code>, <code>should not send parent for root</code>, <code>should ask confirmation before reset</code>, <code>should restore loaded values when reset is confirmed</code>, <code>should show not found message when update returns 404</code>.</li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Contraintes client identiques au legacy (#sec-6) et aux longueurs E-13/E-14 ; serveur autorité</li><li>Promotion/rétrogradation de niveau impossible depuis l&#39;UI (RM-05)</li><li>Pas de génération de slug à l&#39;édition (E-18) ; pas d&#39;unicité de nom contrôlée</li><li>Responsive (colonne unique, champs pleine largeur) et accessible (labels, <code>aria-invalid</code>, <code>aria-describedby</code>)</li></ul></li></ul></li></ul><h4 id="frontend-011-pages-admin-admin-regions-admin-regions-new-admin-regions-id-edit" tabindex="-1">FRONTEND-011 : Pages admin <code>/admin/regions</code>, <code>/admin/regions/new</code>, <code>/admin/regions/:id/edit</code> <a class="header-anchor" href="#frontend-011-pages-admin-admin-regions-admin-regions-new-admin-regions-id-edit" aria-label="Permalink to &quot;FRONTEND-011 : Pages admin `/admin/regions`, `/admin/regions/new`, `/admin/regions/:id/edit`&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Page</li><li><strong>Description</strong> : Pages d&#39;administration enveloppées par <code>AdminAccessGate</code>, assemblant tableau et formulaires.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-009, FRONTEND-010</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : <code>php-legacy/admin/region-list.php</code>, <code>region-create.php</code>, <code>region-edit.php</code>.</li><li><strong>Implémentation selon la documentation</strong> (<code>routing.md</code>) : <ul><li><code>src/app/routes/admin/regions/regions-admin-list.tsx</code> (<code>RegionsAdminListPage</code>), <code>region-create.tsx</code> (<code>RegionCreatePage</code>, lit <code>?parent=</code> pour le défaut), <code>region-edit.tsx</code> (<code>RegionEditPage</code> : <code>useParams</code>, <code>useRegion(id)</code> : skeleton pendant le chargement de l&#39;arbre, id inconnu → « Cette région n&#39;existe pas. » + lien vers la liste, 401/403 → <code>AdminErrorAlert</code>) ; chacune exporte <code>Component</code>.</li><li>Après modification : navigation vers <code>/admin/regions</code> au niveau et à la page d&#39;origine (<code>regionLevelPath</code>). Après création : reste sur la page (spec).</li><li>HTML minimal : <code>h1</code>, <code>AdminAccessGate</code>, fil d&#39;Ariane <code>AdminBreadcrumb</code> (Administration &gt; Régions &gt; Nouvelle région / Modifier).</li><li><strong>Transposition</strong> : le mode « saisie d&#39;Id » du legacy (<code>region-edit.php:110-117</code>, Alt 1 et 2) n&#39;est pas reproduit comme formulaire : les identifiants sont des UUID (choix technique de l&#39;API, #sec-13) et la route exige l&#39;id ; l&#39;id inconnu affiche le message « Region not exist. » traduit avec retour à la liste.</li></ul></li><li><strong>Tests</strong> : tests d&#39;intégration après implémentation (FRONTEND-013).</li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Trois routes rendues sous le gate admin</li><li>Retour au niveau/page d&#39;origine après modification</li><li>Id inconnu ou non UUID géré sans plantage</li></ul></li></ul></li></ul><h4 id="frontend-012-integrer-routes-et-navigation" tabindex="-1">FRONTEND-012 : Intégrer routes et navigation <a class="header-anchor" href="#frontend-012-integrer-routes-et-navigation" aria-label="Permalink to &quot;FRONTEND-012 : Intégrer routes et navigation&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Navigation</li><li><strong>Description</strong> : Déclarer les routes régions (lazy) dans <code>app/router.tsx</code> et ajouter les liens dans <code>AppLayout</code>.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-007, FRONTEND-011</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : <code>php-legacy/templates/layout/page-top.php:41</code> (lien « Regions »), menu admin « Region » (<code>admin/page-left.php:7</code>).</li><li><strong>Implémentation selon la documentation</strong> (<code>routing.md</code>) : <ul><li><code>router.tsx</code> : sous la route <code>/</code> (<code>AppLayout</code>) ajouter <code>regions</code>, <code>admin/regions</code>, <code>admin/regions/new</code>, <code>admin/regions/:id/edit</code> en <code>lazy: () =&gt; import(...)</code>, en conservant le <code>TODO(Authentification)</code> ; ne pas modifier les routes catégories.</li><li><code>AppLayout</code> : ajouter <code>{ to: &#39;/regions&#39;, label: &#39;Régions&#39; }</code> et <code>{ to: &#39;/admin/regions&#39;, label: &#39;Administration des régions&#39; }</code> au tableau <code>navLinks</code> ; le menu reste empilé sous <code>md</code> ; vérifier l&#39;absence de débordement à 320 px avec 4 liens (passer à un menu repliable <code>Sheet</code>/<code>DropdownMenu</code> seulement si nécessaire).</li></ul></li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Navigation fonctionnelle entre <code>/regions</code>, <code>/admin/regions</code> et sous-pages</li><li>Pages chargées en lazy (chunks séparés au <code>npm run build</code>)</li><li>Lien actif marqué <code>aria-current=&quot;page&quot;</code> ; <code>/categories</code> et <code>/admin/categories</code> non régressés (un lien actif ne doit pas masquer l&#39;autre : <code>NavLink</code> de <code>/regions</code> ne correspond pas à <code>/admin/regions</code>)</li></ul></li></ul></li></ul><h4 id="frontend-013-tests-d-integration-des-parcours-et-passe-qualite" tabindex="-1">FRONTEND-013 : Tests d&#39;intégration des parcours et passe qualité <a class="header-anchor" href="#frontend-013-tests-d-integration-des-parcours-et-passe-qualite" aria-label="Permalink to &quot;FRONTEND-013 : Tests d&#39;intégration des parcours et passe qualité&quot;">​</a></h4><ul><li><strong>Type</strong> : Frontend - Tests / Qualité</li><li><strong>Description</strong> : Tests d&#39;intégration MSW des workflows complets (public et admin) avec providers complets, puis passe qualité.</li><li><strong>Status</strong> : Unprocessed</li><li><strong>Dépend de</strong> : FRONTEND-012</li><li><strong>Détails</strong> : <ul><li><strong>Référence source</strong> : scénarios 1 à 7 de <code>output/features/Regions_spec.md</code>.</li><li><strong>Implémentation selon la documentation</strong> (<code>.claude/skills/front-testing-conventions/references/testing.md</code>, <code>tdd-conventions.md</code>) : <ul><li><code>tests/integration/regions-public.integration.test.tsx</code> : <code>/regions?category=voitures</code> via <code>createMemoryRouter</code>, clic sur une sous-région → URL cible <code>/ads?category=voitures&amp;region=...</code>.</li><li><code>tests/integration/regions-admin.integration.test.tsx</code> : sans jeton → formulaire de jeton → liste ; création d&#39;une racine avec « Générer » puis « Créer », message avec lien d&#39;édition ; création d&#39;une sous-région (parent choisi) ; édition d&#39;une sous-région avec changement de racine ; édition d&#39;une racine (pas de select Parent) ; suppression d&#39;une racine avec enfants (409 affiché) puis d&#39;une feuille ; Monter/Descendre ; niveau enfant (<code>?parent=</code>) et retour ; 403 pour un jeton non admin ; id inconnu.</li><li><code>localStorage.clear()</code> dans <code>beforeEach</code> ; QueryClient neuf par test.</li><li>Vérifications manuelles documentées : largeurs 320, 375, 768, 1024, 1440 px, navigation clavier ; <code>npm run lint</code>, <code>npm run typecheck</code>, <code>npm test</code>, <code>npm run test:coverage</code> (hooks/utils &gt;= 90 %, global &gt;= 80 %), <code>npm run build</code>.</li><li>Revue <code>/review:frontend-review</code> en fin de lot ; contrôle final des contrats face à <code>openapi.yaml</code> (BACKEND-020).</li></ul></li><li><strong>Critères d&#39;acceptation</strong> : <ul><li>Tous les tests unitaires et d&#39;intégration passent, y compris ceux de Categories (aucune régression)</li><li>ESLint, Prettier et TypeScript sans erreur</li><li>Responsive et accessibilité (WCAG 2.1 AA) vérifiés</li></ul></li></ul></li></ul><h2 id="architecture-frontend" tabindex="-1">Architecture Frontend <a class="header-anchor" href="#architecture-frontend" aria-label="Permalink to &quot;Architecture Frontend&quot;">​</a></h2><h3 id="configuration-api" tabindex="-1">Configuration API <a class="header-anchor" href="#configuration-api" aria-label="Permalink to &quot;Configuration API&quot;">​</a></h3><ul><li><strong>Tâches</strong> : FRONTEND-001, FRONTEND-003, FRONTEND-004</li><li><strong>Approche</strong> : <code>api/region.ts</code> d&#39;appels directs <code>apiClient</code>, chemins <code>/api/...</code>, client existant réutilisé (<code>.claude/skills/front-app-conventions/references/api-integration.md</code>).</li><li><strong>Configuration</strong> : <code>VITE_API_BASE_URL</code> = origine (déjà en place), aucune nouvelle variable.</li><li><strong>Schémas</strong> : <code>types/region.ts</code> + <code>schemas/region.ts</code>.</li></ul><h3 id="composants-ui" tabindex="-1">Composants UI <a class="header-anchor" href="#composants-ui" aria-label="Permalink to &quot;Composants UI&quot;">​</a></h3><ul><li><strong>Tâches</strong> : FRONTEND-006 à FRONTEND-010</li><li><strong>Approche</strong> : features dans <code>src/features/regions/</code> (public, <code>region-select</code>, <code>admin/</code>), composants Shadcn existants, aucun ajout dans <code>components/ui/</code>.</li><li><strong>Library UI</strong> : Tailwind 4 + Shadcn/ui + lucide-react + sonner.</li><li><strong>Responsive</strong> : mobile-first (<code>grid-cols-1 sm:grid-cols-2 lg:grid-cols-3</code>, <code>hidden sm:table-cell</code>, tableau défilant, zones tactiles &gt;= 44 px), sans pixels codés en dur (<code>.claude/skills/front-design-conventions</code>).</li></ul><h3 id="gestion-d-etat" tabindex="-1">Gestion d&#39;État <a class="header-anchor" href="#gestion-d-etat" aria-label="Permalink to &quot;Gestion d&#39;État&quot;">​</a></h3><ul><li><strong>Tâches</strong> : FRONTEND-005</li><li><strong>Approche</strong> : React Query pour toutes les données serveur ; niveau et page dans l&#39;URL ; <code>useState</code> local pour les dialogues ; aucun store Zustand (<code>state-management.md</code>).</li><li><strong>Persistance</strong> : jeton <code>localStorage[&#39;auth-token&#39;]</code> (existant).</li><li><strong>Cache</strong> : arbre <code>staleTime</code> 5 min ; invalidation de <code>[&#39;regions&#39;]</code> après chaque écriture.</li></ul><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><strong>Tâches</strong> : FRONTEND-011, FRONTEND-012</li><li><strong>Approche</strong> : React Router 7, routes lazy, pages suffixées <code>Page</code>.</li><li><strong>Protection</strong> : <code>AdminAccessGate</code> + 401/403 backend ; migration future vers <code>authLoader</code> (feature Authentification).</li><li><strong>Structure</strong> : <code>/regions</code>, <code>/admin/regions</code>, <code>/admin/regions/new</code>, <code>/admin/regions/:id/edit</code>.</li></ul><h2 id="tests-frontend" tabindex="-1">Tests Frontend <a class="header-anchor" href="#tests-frontend" aria-label="Permalink to &quot;Tests Frontend&quot;">​</a></h2><h3 id="strategie-test-first" tabindex="-1">Stratégie Test First <a class="header-anchor" href="#strategie-test-first" aria-label="Permalink to &quot;Stratégie Test First&quot;">​</a></h3><p>Test First pour : schémas et utilitaires (002), couche API (004), hooks (005), <code>RegionTree</code> (007), <code>RegionSelect</code> (008), <code>RegionAdminTable</code> (009), <code>RegionForm</code> (010). Pas de Test First pour : types (001), fixtures/handlers (003, infrastructure), <code>AdminBreadcrumb</code> (006, composant sans logique), pages et routes (011, 012 : tests d&#39;intégration après implémentation, 013).</p><h3 id="tests-selon-documentation" tabindex="-1">Tests selon Documentation <a class="header-anchor" href="#tests-selon-documentation" aria-label="Permalink to &quot;Tests selon Documentation&quot;">​</a></h3><p>Conventions de <code>.claude/skills/front-testing-conventions</code> : MSW pour tous les appels (jamais de mock de composants, RHF ou React Query), <code>createApiUrl(path)</code>, collections toujours en <code>{ data, meta }</code> sauf l&#39;arbre <code>{ data }</code>, nommage <code>should {behavior} when {condition}</code>, pattern AAA, globals Vitest sans import, <code>tests/unit/**</code> et <code>tests/integration/*.integration.test.tsx</code>. Ne pas tester <code>components/ui/</code>, les types ni la configuration du routeur.</p><h2 id="ordre-d-execution-frontend" tabindex="-1">Ordre d&#39;Exécution Frontend <a class="header-anchor" href="#ordre-d-execution-frontend" aria-label="Permalink to &quot;Ordre d&#39;Exécution Frontend&quot;">​</a></h2><ol><li><strong>Fondations</strong> : FRONTEND-001 → FRONTEND-002 → FRONTEND-003 → FRONTEND-004 <ul><li><em>Justification</em> : types, validations et mocks précèdent la couche API et ses tests ; le client HTTP est déjà en place.</li></ul></li><li><strong>Logique métier</strong> : FRONTEND-005 (dépend de 004) ; FRONTEND-006 (dépend de 001, parallélisable) <ul><li><em>Justification</em> : hooks de cache et mutations ; fil d&#39;Ariane générique prêt avant les pages admin.</li></ul></li><li><strong>Features</strong> : FRONTEND-007, FRONTEND-008 (dépendent de 005) → FRONTEND-009 (005, 006) → FRONTEND-010 (002, 005, 008) <ul><li><em>Justification</em> : le select partagé sert au champ Parent du formulaire.</li></ul></li><li><strong>Interfaces</strong> : FRONTEND-011 → FRONTEND-012 → FRONTEND-013 <ul><li><em>Justification</em> : assemblage en pages, câblage routes/navigation, puis parcours complets et qualité.</li></ul></li></ol><p><strong>Note</strong> : tests écrits AVANT chaque tâche de logique (Test First). Les tâches FRONTEND-004 à 013 supposent les endpoints BACKEND-013 à 019 livrés pour la validation réelle ; le développement frontend se fait contre MSW.</p><h2 id="risques-et-points-d-attention" tabindex="-1">Risques et Points d&#39;Attention <a class="header-anchor" href="#risques-et-points-d-attention" aria-label="Permalink to &quot;Risques et Points d&#39;Attention&quot;">​</a></h2><h3 id="risques-techniques-frontend" tabindex="-1">Risques Techniques Frontend <a class="header-anchor" href="#risques-techniques-frontend" aria-label="Permalink to &quot;Risques Techniques Frontend&quot;">​</a></h3><ul><li><strong>Spec API non encore publiée</strong> : <ul><li><strong>Description</strong> : <code>openapi.yaml</code> ne contient pas les chemins régions ; les types et handlers MSW sont déduits de l&#39;analyse backend (noms <code>childcount</code>, <code>parent</code>, absence de <code>position</code>).</li><li><strong>Impact</strong> : Élevé (erreurs runtime si le contrat final diffère).</li><li><strong>Atténuation</strong> : revérifier chaque type et handler face à <code>openapi.yaml</code> dès BACKEND-020 (FRONTEND-013) ; une divergence se corrige dans <code>types/region.ts</code> et <code>region-handlers.ts</code> uniquement.</li></ul></li><li><strong>Absence de <code>GET /api/admin/regions/{id}</code></strong> : <ul><li><strong>Description</strong> : l&#39;édition lit la région dans l&#39;arbre public.</li><li><strong>Impact</strong> : Faible/Moyen (cache de 5 min ; id obsolète).</li><li><strong>Atténuation</strong> : l&#39;arbre est invalidé après chaque écriture ; <code>useRegion</code> retourne <code>undefined</code> si l&#39;id n&#39;existe plus (message « Cette région n&#39;existe pas. »).</li></ul></li><li><strong>Divergences de contrat avec Categories</strong> : <ul><li><strong>Description</strong> : <code>parent</code>/<code>childcount</code>/PUT/slug obligatoire, risque de copie erronée du code catégories.</li><li><strong>Impact</strong> : Moyen. <strong>Atténuation</strong> : tableau « Différences avec Categories » et tests dédiés.</li></ul></li><li><strong>Langue des messages serveur</strong> : <ul><li><strong>Description</strong> : les messages de violation backend (« Invalid name! », etc.) sont en anglais, l&#39;interface est en français.</li><li><strong>Impact</strong> : Faible (incohérence de langue). <strong>Atténuation</strong> : le client valide d&#39;abord via Zod en français ; les erreurs serveur 422 non prévues par le client sont affichées telles quelles via <code>handleFormErrors</code>. À signaler à l&#39;utilisateur pour décision (voir retour).</li></ul></li><li><strong>Route <code>/ads</code> inexistante</strong> : <ul><li><strong>Description</strong> : les liens publics mènent à <code>NotFound</code> tant que la feature Recherche n&#39;est pas migrée.</li><li><strong>Impact</strong> : Faible. <strong>Atténuation</strong> : constante <code>SEARCH_ROUTE</code> partagée.</li></ul></li><li><strong>Bundle / performance</strong> : pages en lazy loading ; aucune nouvelle dépendance.</li><li><strong>États d&#39;erreur non gérés</strong> : <code>AdminErrorAlert</code> pour 401/403/réseau ; <code>ErrorBoundary</code> global existant.</li></ul><h3 id="considerations-ux-ui" tabindex="-1">Considérations UX/UI <a class="header-anchor" href="#considerations-ux-ui" aria-label="Permalink to &quot;Considérations UX/UI&quot;">​</a></h3><p>Mobile-first, unités relatives uniquement, zones tactiles &gt;= 44 px, <code>aria-label</code> sur les boutons icône, <code>role=&quot;alert&quot;</code> pour les erreurs, focus visible, tests aux largeurs 320, 375, 768, 1024, 1440.</p><h3 id="integration-backend" tabindex="-1">Intégration Backend <a class="header-anchor" href="#integration-backend" aria-label="Permalink to &quot;Intégration Backend&quot;">​</a></h3><p><code>apiClient</code> avec <code>skipAuth</code> sur l&#39;arbre public, jeton Bearer sur <code>/api/admin/**</code>, aucun <code>/api/api</code>. Pas d&#39;optimistic update (l&#39;ordre est calculé par le serveur). Un 422 de génération de slug n&#39;est pas une erreur de page : il alimente le champ Nom.</p><h2 id="considerations-de-migration-frontend" tabindex="-1">Considérations de Migration Frontend <a class="header-anchor" href="#considerations-de-migration-frontend" aria-label="Permalink to &quot;Considérations de Migration Frontend&quot;">​</a></h2><h3 id="defis-techniques" tabindex="-1">Défis Techniques <a class="header-anchor" href="#defis-techniques" aria-label="Permalink to &quot;Défis Techniques&quot;">​</a></h3><ul><li><strong>Génération de slug côté serveur</strong> : <ul><li><strong>Problème</strong> : le legacy génère le slug par soumission du formulaire ; Categories génère un aperçu client.</li><li><strong>Contexte source</strong> : <code>region-create.php:54-69</code>, <code>slug()</code> avec <code>iconv</code>.</li><li><strong>Solution cible</strong> : bouton « Générer » → <code>POST /api/admin/regions/slug</code> (RM-12 appliquée par le serveur), sans réimplémenter l&#39;algorithme (<code>lib/slug.ts</code> non utilisé).</li><li><strong>Complexité</strong> : Faible.</li></ul></li><li><strong>Règle RM-05 (parent restreint)</strong> : <ul><li><strong>Problème</strong> : contrairement à Categories, ni promotion ni rétrogradation.</li><li><strong>Solution cible</strong> : select Parent absent pour une racine ; sans option « Aucune » pour une sous-région ; le serveur ignore sinon le parent.</li><li><strong>Complexité</strong> : Faible.</li></ul></li><li><strong>Pas d&#39;endpoint de détail</strong> : lecture via l&#39;arbre (voir risques). <strong>Complexité</strong> : Faible.</li><li><strong>Fidélité vs UX</strong> : Up/Down toujours actifs, colonnes legacy, formulaire vidé après création : choix de fidélité (#sec-3, CL-10) assumés malgré des patterns plus riches dans Categories.</li></ul><h3 id="patterns-specifiques-a-la-source-a-adapter" tabindex="-1">Patterns Spécifiques à la Source à Adapter <a class="header-anchor" href="#patterns-specifiques-a-la-source-a-adapter" aria-label="Permalink to &quot;Patterns Spécifiques à la Source à Adapter&quot;">​</a></h3><ul><li><strong>Propagation des GET (<code>build_query_string</code>)</strong> : <ul><li><strong>Dans la source</strong> : fusion de la query string courante dans chaque lien.</li><li><strong>Équivalent cible</strong> : <code>buildRegionSearchPath</code> sur <code>URLSearchParams</code>.</li><li><strong>Chemin de migration</strong> : copier les paramètres, retirer <code>id</code>/<code>code</code>/<code>page</code>, définir <code>region</code>.</li></ul></li><li><strong>Select inline dupliqué (5 copies)</strong> : un composant <code>RegionSelect</code> unique.</li><li><strong>Multi-submit Generate/Create</strong> : deux actions distinctes (mutation de génération, mutation de création).</li><li><strong>Confirmation <code>confirm()</code></strong> : <code>AlertDialog</code> Shadcn pour suppression et réinitialisation.</li><li><strong>Mutations par GET</strong> : remplacées par DELETE/POST (T-02).</li></ul><h3 id="meilleures-pratiques-de-la-stack-frontend-cible" tabindex="-1">Meilleures Pratiques de la Stack Frontend Cible <a class="header-anchor" href="#meilleures-pratiques-de-la-stack-frontend-cible" aria-label="Permalink to &quot;Meilleures Pratiques de la Stack Frontend Cible&quot;">​</a></h3><ul><li><strong>Flux Route → Feature → Hook → API</strong> : les features n&#39;appellent jamais <code>regionApi</code> directement (<code>.claude/skills/front-app-conventions/references/architecture.md</code>).</li><li><strong>Query keys hiérarchiques et invalidation</strong> par <code>regionKeys.all</code> après toute écriture (<code>state-management.md</code>).</li><li><strong>Erreurs centralisées</strong> : <code>handleApiError</code> / <code>handleFormErrors</code> ; <code>catch (error: unknown)</code> puis <code>error instanceof ApiError &amp;&amp; error.data?.code === &#39;...&#39;</code> (<code>api-integration.md</code>).</li><li><strong>Tailwind mobile-first</strong> sans CSS custom ni valeur arbitraire en px (<code>styling.md</code>, <code>front-design-conventions</code>).</li><li><strong>Tests</strong> : MSW, aucun mock de composants (<code>.claude/skills/front-testing-conventions/references/mocking-strategies.md</code>).</li></ul>',100)])])}const m=o(r,[["render",s]]);export{p as __pageData,m as default};
